/* ==============================================================================================
 * TASK Task_LightCtl   (EXTENDED, priority 3, activation limit 1, stack 384 words, autostart in OSDEFAULTAPPMODE)
 *
 * Why this task exists: RteEventToTaskMapping (ECUC_Rte_09020) entries in config/ecuc/LightEcu.ecuc.json put these runnables here:
 *   RtePositionInTask 1  runnable LightCtl_Run20ms  <- TE_LightCtl_20ms (TimingEvent 20 ms)
 *     raised by OsAlarm Alarm_LightCtl20ms (autostart REL start=20 cycle=20 ticks => RteActivationOffset 20 ms, period 20 ms): SETEVENT Ev_LightCtl_Timer20ms
 *     disabledInMode POST_RUN: skipped while the mode is active (the alarm keeps running, only the runnable is suppressed)
 *   RtePositionInTask 2  runnable LightCtl_OnSpeed  <- DRE_LightCtl_VehicleSpeed (DataReceivedEvent R_VehicleSpeed.VehicleSpeed)
 *     raised by Com notification Rte_COMCbk_VehicleSpeed() (Rte.c) -> SetEvent(Ev_LightCtl_VehicleSpeed)
 *   RtePositionInTask 3  runnable LightCtl_OnModeSwitch  <- MSE_LightCtl_EnterRun (ModeSwitchEvent ON-ENTRY R_EcuMode RUN), MSE_LightCtl_EnterPostRun (ModeSwitchEvent ON-ENTRY R_EcuMode POST_RUN)
 *     raised by Rte_Switch_P_EcuMode_EcuMode (Rte.c) when the mode is entered -> SetEvent(Ev_LightCtl_ModeSwitch)
 * ============================================================================================== */
TASK(Task_LightCtl)
{
    EventMaskType ev = 0u;

    for (;;)                          /* extended task: never terminates, it parks in WaitEvent */
    {
        (void)WaitEvent(Ev_LightCtl_Timer20ms | Ev_LightCtl_VehicleSpeed | Ev_LightCtl_ModeSwitch);
        (void)GetEvent(Task_LightCtl, &ev);
        (void)ClearEvent(ev);             /* consume what we serve now; events set meanwhile stay pending */

        if ((ev & Ev_LightCtl_Timer20ms) != 0u)
        {
            /* position 1: LightCtl_Run20ms <- TE_LightCtl_20ms */
            if (Rte_Mode_EcuMode != RTE_MODE_EcuMode_POST_RUN)         /* disabledInMode */
            {
                LightCtl_Run20ms();
            }
        }
        if ((ev & Ev_LightCtl_VehicleSpeed) != 0u)
        {
            /* position 2: LightCtl_OnSpeed <- DRE_LightCtl_VehicleSpeed */
            Rte_CopyIn_LightCtl_OnSpeed();      /* implicit read: snapshot before the runnable starts */
            LightCtl_OnSpeed();
        }
        if ((ev & Ev_LightCtl_ModeSwitch) != 0u)
        {
            /* position 3: LightCtl_OnModeSwitch <- MSE_LightCtl_EnterRun, MSE_LightCtl_EnterPostRun */
            LightCtl_OnModeSwitch();
        }
    }
}

/* ==============================================================================================
 * TASK Task_LightAct   (BASIC, priority 2, activation limit 2, stack 256 words)
 *
 * Why this task exists: RteEventToTaskMapping (ECUC_Rte_09020) entries in config/ecuc/LightEcu.ecuc.json put these runnables here:
 *   RtePositionInTask 1  runnable Actuator_OnCmd  <- DRE_Actuator_HeadlightCmd (DataReceivedEvent R_HeadlightCmd.HeadlightCmd)
 *     raised by the on-ECU provider's Rte_Write (Rte.c Rte_Sink_*) -> ActivateTask
 * ============================================================================================== */
TASK(Task_LightAct)
{
    /* position 1: Actuator_OnCmd <- DRE_Actuator_HeadlightCmd */
    Actuator_OnCmd();

    (void)TerminateTask();            /* basic task: one activation = one run to completion */
}

